css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 9px 14px; margin-bottom: 12px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 5px;}
.mz .recuerda-cuerpo{font-size: 15px; line-height: 1.55;}
.mz .recuerda-cuerpo b{font-size: 17px;}
.mz .serie-cajas{display: flex; gap: 8px; flex-wrap: wrap; font-size: 18px; font-weight: 700; align-items: center;}
.mz .serie-cajas .caja-num{width: 58px; height: 42px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .serie-cajas .salto{font-size: 13px; font-family: sans-serif;}
.mz .serie-label{font-size: 13px; font-weight: 600; font-family: sans-serif; margin-bottom: 4px;}
.mz .serie-block{margin-bottom: 9px;}
.mz .salto-fila{display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 18px; font-weight: 700; margin-bottom: 9px;}
.mz .salto-fila .caja-num{width: 56px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; background: #f3f3f3;}
.mz .salto-fila .resp{margin-left: 8px; font-size: 14px; font-weight: 600; display: flex; align-items: center; gap: 6px;}
.mz .salto-fila .resp .caja-salto{width: 60px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .recuerda-cuerpo{line-height: 1.725 !important;}
